for name, spec in patches.items():
 path=Path(name);data=path.read_bytes()
 assert hashlib.sha256(data).hexdigest()==spec['before'], f"Concurrent change: {name}"
 lines=data.decode().splitlines(keepends=True)
 for begin,end,new in reversed(spec['changes']):lines[begin:end]=[new]
 output=''.join(lines).encode()
 assert hashlib.sha256(output).hexdigest()==spec['after'], f"Patch mismatch: {name}"
 path.write_bytes(output)
print('Checked shared-reference source patch prepared. No production data/settings touched.')
